from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    balanced_groups = []  # Step 2: Initialize an empty list to store the balanced groups
    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                balanced_groups.append(paren_string[start:i + 1])  # Step 4: Add balanced group to the list

    return balanced_groups  # Step 5: Return the list of balanced groups

